+    fn validate_slot_roster(release: &ProductReleaseId, slots: &[ReleaseArtifactSlot]) -> Result<(), SuccessorError> {
+        if slots.windows(2).any(|pair| pair[0] == pair[1]) {
+            return Err(SuccessorError::DuplicateSlot);
+        }
+        for slot in slots {
+            slot.validate(release)?;
+        }
+        let targets: BTreeSet<_> = slots
+            .iter()
+            .filter_map(|slot| match slot {
+                ReleaseArtifactSlot::ProductAsset { target, .. } => Some(*target),
+                _ => None,
+            })
+            .collect();
+        if targets.len() != ProductTarget::ALL.len()
+            || !ProductTarget::ALL.iter().all(|target| targets.contains(target))
+            || slots.iter().filter(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. })).count() != 1
+            || slots.iter().filter(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. })).count() != 1
+        {
+            return Err(SuccessorError::InvalidProductRoster);
+        }
+        let mut names = BTreeSet::new();
+        if slots.iter().any(|slot| !names.insert(slot.file_name())) {
+            return Err(SuccessorError::DuplicateFileName);
+        }
+        Ok(())
+    }
+
+    fn validate_operations(
+        release: &ProductReleaseId,
+        operations: &[ReleaseOperation],
+        slots: &[ReleaseArtifactSlot],
+    ) -> Result<(), SuccessorError> {
+        let ids: BTreeSet<_> = operations.iter().map(|operation| operation.id.clone()).collect();
+        if ids.len() != operations.len() {
+            return Err(SuccessorError::DuplicateOperation);
+        }
+        for operation in operations {
+            operation.id.validate(release)?;
+            if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1])
+                || operation.prerequisites.iter().any(|id| !ids.contains(id))
+            {
+                return Err(SuccessorError::InvalidPrerequisite);
+            }
+        }
+        let expected_uploads: BTreeSet<_> = slots
+            .iter()
+            .filter(|slot| slot.release().is_some())
+            .cloned()
+            .collect();
+        let uploads: BTreeSet<_> = operations
+            .iter()
+            .filter_map(|operation| match &operation.id {
+                ReleaseOperationId::ArtifactUpload { slot, .. } => Some(slot.clone()),
+                _ => None,
+            })
+            .collect();
+        if uploads != expected_uploads {
+            return Err(SuccessorError::InvalidProductRoster);
+        }
+        let tags = operations
+            .iter()
+            .filter(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
+            .count();
+        let prepares = operations
+            .iter()
+            .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
+            .count();
+        let publishes = operations
+            .iter()
+            .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
+            .count();
+        if tags != 1 || prepares != 1 || publishes != 1 {
+            return Err(SuccessorError::InvalidProductOperation);
+        }
+        let edges: BTreeMap<_, _> = operations
+            .iter()
+            .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
+            .collect();
+        let canonical = stable_order(&edges)?;
+        if operations.iter().map(|operation| &operation.id).ne(canonical.iter()) {
+            return Err(SuccessorError::NonCanonicalOperationOrder);
+        }
+        Ok(())
+    }
+
+    fn stable_order(
+        prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
+    ) -> Result<Vec<ReleaseOperationId>, SuccessorError> {
+        let mut remaining: BTreeMap<_, _> = prerequisites
+            .iter()
+            .map(|(id, prerequisites)| (id.clone(), prerequisites.len()))
+            .collect();
+        let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
+        for (id, prerequisites) in prerequisites {
+            for prerequisite in prerequisites {
+                dependents.entry(prerequisite.clone()).or_default().push(id.clone());
+            }
+        }
+        let mut ready: BTreeSet<_> = remaining
+            .iter()
+            .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
+            .collect();
+        let mut ordered = Vec::with_capacity(prerequisites.len());
+        while let Some(id) = ready.pop_first() {
+            ordered.push(id.clone());
+            for dependent in dependents.get(&id).into_iter().flatten() {
+                let count = remaining.get_mut(dependent).expect("known successor node");
+                *count -= 1;
+                if *count == 0 {
+                    ready.insert(dependent.clone());
+                }
+            }
+        }
+        (ordered.len() == prerequisites.len())
+            .then_some(ordered)
+            .ok_or(SuccessorError::CyclicPrerequisites)
+    }
+
+    fn digest_intent(
+        release: &ProductReleaseId,
+        source: &CommitSha,
+        operations: &[ReleaseOperation],
+        slots: &[ReleaseArtifactSlot],
+    ) -> IntentDigest {
+        let mut transcript = CanonicalTranscript::intent_v1();
+        transcript.push_str("successor.schema", "1");
+        transcript.push_str("product", release.product.as_str());
+        transcript.push_str("product.version", release.version.render());
+        transcript.push_str("source", source.as_str());
+        for operation in operations {
+            transcript.push_bytes("operation", serde_json::to_vec(&operation.id).expect("closed operation serializes"));
+            for prerequisite in &operation.prerequisites {
+                transcript.push_bytes("prerequisite", serde_json::to_vec(prerequisite).expect("closed operation serializes"));
+            }
+        }
+        for slot in slots {
+            transcript.push_bytes("slot", serde_json::to_vec(slot).expect("closed slot serializes"));
+        }
+        IntentDigest::from_transcript(&transcript)
+    }
