+    fn checksum_roster(
+        intent: &ReleaseIntent,
+        manifest: &ReleaseArtifactManifest,
+        metadata_digest: ArtifactDigest,
+    ) -> Result<Vec<ChecksumRosterEntry>, SuccessorError> {
+        manifest.validate_for_intent(intent)?;
+        let mut entries = manifest
+            .entries
+            .iter()
+            .filter_map(|entry| match entry.slot {
+                ReleaseArtifactSlot::ProductAsset { .. } | ReleaseArtifactSlot::ReleaseMetadata { .. } => {
+                    Some(ChecksumRosterEntry {
+                        file_name: entry.slot.file_name().to_string(),
+                        digest: if matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }) {
+                            metadata_digest.clone()
+                        } else {
+                            entry.digest.clone()
+                        },
+                    })
+                }
+                ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ChecksumManifest { .. } => None,
+            })
+            .collect::<Vec<_>>();
+        entries.sort_by(|left, right| left.file_name.cmp(&right.file_name));
+        if entries.len() != 5 || entries.iter().any(|entry| entry.file_name == CHECKSUM_FILE_NAME)
+            || entries.windows(2).any(|pair| pair[0].file_name == pair[1].file_name)
+        {
+            return Err(SuccessorError::InvalidChecksumRoster);
+        }
