+    fn digest_intent(
+        release: &ProductReleaseId,
+        source: &CommitSha,
+        operations: &[ReleaseOperation],
+        slots: &[ReleaseArtifactSlot],
+    ) -> IntentDigest {
+        let mut transcript = CanonicalTranscript::intent_v1();
+        transcript.push_str("successor.schema", "1");
+        transcript.push_str("product", release.product.as_str());
+        transcript.push_str("product.version", release.version.render());
+        transcript.push_str("source", source.as_str());
+        for operation in operations {
+            transcript.push_bytes("operation", serde_json::to_vec(&operation.id).expect("closed operation serializes"));
+            for prerequisite in &operation.prerequisites {
+                transcript.push_bytes("prerequisite", serde_json::to_vec(prerequisite).expect("closed operation serializes"));
+            }
+        }
+        for slot in slots {
+            transcript.push_bytes("slot", serde_json::to_vec(slot).expect("closed slot serializes"));
+        }
+        IntentDigest::from_transcript(&transcript)
+    }
